"""Автономный отчёт: перенос известных утверждений отделён от новых гипотез."""
import json


def markdown_report(sealed, evaluation, comparison):
    summary = comparison["summary"]
    unique = summary["unique_target_knowledge_by_relation"]
    lines = ["# Исправленное сравнение и прогноз по пяти источникам", "",
        "Все карты сохранены в утверждённых запусках. Промпты, графы и полный текст не пересобирались. LLM, переводчик и эмбеддинги не вызывались. Целевая статья использовалась ранее для отладки: это проверка изоляции алгоритма, а не независимое проспективное испытание.", "",
        "## Исправление сравнения", "",
        f'Нормализатор {comparison["analysis"]["normalizer_version"]}; сравнитель {comparison["analysis"]["comparator_version"]}. Описательная копия текста отделена от фактов в {summary["auxiliary_description_count"]} утверждениях цели и сохранена в auxiliary_attributes. Явные границы процентного диапазона и запись интервала приводятся к одной форме. Отрицания, группы, время и размерности сохранены.', "",
        f'Цель: {comparison["analysis"]["target_knowledge_count"]} блоков. Пятёрка: {comparison["analysis"]["source_knowledge_count"]} блоков; {comparison["analysis"]["pair_count"]} пар.', "",
        f'Полная эквивалентность: {len(unique["equivalent"])} блоков; частичное сходство: {len(unique["partial"])}; общий шаблон: {len(unique["template"])}. Частичных пар: {summary["relations"].get("partial",0)}. Категории могут пересекаться; 17 пар не означают 17 знаний.', "",
        f'Совпавшие параметры найдены в блоках: {summary["shared_attribute_targets"]}. Это совпадение части содержания, без утверждения эквивалентности целого блока или его контекста.', "",
        "## Изоляция прогноза", "",
        f'Прогноз {sealed["run_id"]}; SHA-256 содержимого зафиксированного прогноза: {evaluation["binding"]["prediction_sha256"]}. Оценка: {evaluation["evaluation_id"]}.', "",
        "Процесс seal получает только массив пяти ссылок на исходные запуски. Кандидаты и правила публикуются атомарно и неизменяемо. Отдельный процесс evaluate читает seal, проверяет его хеш, затем загружает цель. Контроль цитирования поступает только в оценщик. Квитанции отражают пять прочитанных источников в первом процессе и единственный целевой запуск во втором.", "",
        "Обобщаются участники и локальная область когорты. Правило с такой областью применяется внутри одного источника, затем возвращается конкретная область статьи. Когорты разных исследований не объединяются. Отдельные группы альтернативных переходов не превращаются в одну совокупность предпосылок.", "",
        f'Исходных утверждений: {sealed["source_statement_count"]}; допустимых для обучения: {sealed["eligible_statement_count"]}. Минимальная поддержка — две разные статьи, до трёх атомарных предпосылок, до двадцати новых гипотез. Числовые значения, отрицания, модальность, статус действия и контекст не обобщаются.', "",
        "| Режим | Кандидаты | Совпавшие компоненты цели | Полностью покрытые блоки | Блоки с частичным сходством | Блоки с общим параметром |", "|---|---:|---:|---:|---:|---:|"]
    for mode in ("known_union", "semantic", "graph"):
        m = evaluation["modes"][mode]
        lines.append(f'| {mode} | {m["candidate_count"]} | {len(m["matched_target_statements"])} | {len(m["fully_covered_target_blocks"])} | {len(m["partial_target_knowledge"])} | {len(m["shared_attribute_targets"])} |')
    lines += ["", "known_union — перенос уже известных утверждений; semantic и graph — новые статистические гипотезы. Общее число исходных утверждений не ограничивается двадцатью. Совпавший компонент не означает полного покрытия составного блока. Для противопоставлений и аргументов совпадение отдельных частей не подтверждает всё построение.", "",
              "## Цитирование и новые выводы", ""]
    known = evaluation["modes"]["known_union"]
    lines += [f'Совпавшие параметры в контрольных местах цитирования: {known["shared_attributes_by_citation"]["citation_control_anchor"]}. За пределами этих мест: {known["shared_attributes_by_citation"]["no_direct_citation_to_five"]}.', "",
        "Для PMC10000452 общий параметр — диапазон перехода MCI в деменцию 6–44,8% из PMC8918697. Дополнительные ограничения обзора (группы стран, неоднородные определения и периоды наблюдения) сохраняются: перенос числа не делает весь целевой блок эквивалентным исходному. По ссылке [6] проценты и частоты на 1000 человеко-лет остаются различными.", "",
        "Контрольная привязка, абзац с неразрешённой областью цитаты и отсутствие прямой ссылки на пятёрку учитываются отдельно. Отсутствие прямой ссылки не устанавливает новизну относительно всей литературы. Поиск 5/7 контрольных фрагментов первым в выдаче — метрика поиска с известным запросом, а не вероятность предсказания статьи.", "",
        "Новых гипотез на этой пятёрке нет: ни один допустимый шаблон не получил поддержку двух разных источников. Таким прогоном предсказание нового знания цели не продемонстрировано. Это результат выбранного консервативного алгоритма и его ограничений, а не доказательство невозможности вывода из корпуса.", "",
        "## Диагностика и ограничения", "",
        "Неполная атомизация отдельных исходных semantic_frame остаётся диагностикой: общее определение и критерии конкретного протокола могут быть записаны одним утверждением. Свободное описание не дробится в автоматически доказанные факты. Уже явные утверждения составного блока сопоставляются по отдельности, с сохранением логики целого. Данный отчёт не скрывает это ограничение и не повышает совпадения удалением научных ограничений.", "",
        "В режиме semantic поиск ограничен двенадцатью соседями по общим участникам; в режиме graph используются полные группы до трёх атомарных предпосылок. Более широкие группы и неизвестный контекст не используются для обучения. Отсутствие кандидата в цели не является опровержением.", "",
        "Диагностика правил:", "", "```json", json.dumps(sealed["diagnostics"], ensure_ascii=False, indent=2), "```", "",
        "Модельные вызовы: 0. Расход токенов Codex недоступен и не выдумывался. Требуется экспертная проверка семантики, контрольных пар и научных выводов. Следующий независимый эксперимент требует ранее не использованной целевой статьи после фиксации правил."]
    return "\n".join(lines)+"\n"


def render_report(sealed, evaluation):
    data = json.dumps({"sealed": sealed, "evaluation": evaluation}, ensure_ascii=False, separators=(",", ":"))
    return TEMPLATE.replace("__DATA__", data.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029"))


TEMPLATE = r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Прогноз по пяти источникам</title>
<style>body{font:15px/1.5 system-ui;background:#f8fafc;color:#172033;max-width:1450px;margin:auto;padding:24px}button,select,a.button{font:inherit;padding:8px 12px;border:1px solid #94a3b8;border-radius:7px;background:white;color:#172033}button,a.button{cursor:pointer}a.button{display:inline-block;background:#2563eb;color:white;text-decoration:none}table{border-collapse:collapse;width:100%;background:white}th,td{padding:10px;border:1px solid #cbd5e1;text-align:left}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:white;padding:14px;border:1px solid #cbd5e1;max-height:550px;overflow:auto}tr.selected{background:#dbeafe}tbody tr{cursor:pointer}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.notice{padding:16px;border:1px solid #cbd5e1;background:white}code{overflow-wrap:anywhere}</style>
<h1 id="title">Прогноз по пяти источникам</h1><div class="toolbar"><a class="button" href="comparison/comparison.html">Сравнение / Comparison</a><a class="button" href="report.ru.md">Русский отчёт</a><a class="button" href="predictions.json">Зафиксированные кандидаты JSON</a><a class="button" href="evaluation.json">Оценка JSON</a><select id="language"><option value="ru">Русский</option><option value="en">English</option></select></div>
<p class="notice" id="notice"></p><div id="summary"></div><div class="toolbar"><select id="mode"><option value="known_union">Известные утверждения / Known union</option><option value="semantic">Новые гипотезы без связей / Semantic hypotheses</option><option value="graph">Новые гипотезы со связями / Graph hypotheses</option></select><select id="filter"><option value="all">Все / All</option><option value="equivalent">Полное совпадение / Equivalent</option><option value="partial">Частичное сходство / Partial</option><option value="parameter">Общий параметр / Shared attribute</option></select></div>
<table><thead><tr><th id="candidateHeading">Кандидат</th><th id="matchHeading">Соответствия</th></tr></thead><tbody id="rows"></tbody></table><div class="toolbar"><button id="prev">←</button><span id="page"></span><button id="next">→</button></div><h3 id="detailsHeading">Утверждение, исходные фрагменты и ограничения</h3><pre id="details"></pre><details><summary>Версии / Versions</summary><pre id="versions"></pre></details>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let offset=0;
function text(ru,en){return $('language').value==='ru'?ru:en}
function render(){const mode=$('mode').value,evalMode=D.evaluation.modes[mode],candidates=D.sealed.predictions[mode];
$('title').textContent=text('Прогноз по пяти источникам','Prediction from five sources');$('notice').textContent=text('Кандидаты зафиксированы до загрузки цели. Известные утверждения и новые статистические гипотезы учитываются отдельно. Требуется экспертная проверка; эта цель использовалась ранее для отладки. Модельные вызовы: 0.','Candidates were sealed before loading the target. Known statements and novel statistical hypotheses are separate. Expert review is required; this target was inspected earlier during debugging. Model calls: 0.');
$('summary').textContent=text('Кандидатов: ','Candidates: ')+evalMode.candidate_count+text(' · полностью покрытых блоков цели: ',' · fully covered target blocks: ')+evalMode.fully_covered_target_blocks.length+text(' · блоков с общим параметром: ',' · blocks with a shared attribute: ')+evalMode.shared_attribute_targets.length;
$('candidateHeading').textContent=text('Кандидат','Candidate');$('matchHeading').textContent=text('Соответствия','Matches');$('detailsHeading').textContent=text('Утверждение, происхождение и ограничения','Statement, provenance and constraints');
const observations=new Map(evalMode.results.map(r=>[r.candidate_id,r]));let values=candidates.filter(c=>{let r=observations.get(c.id),f=$('filter').value;return f==='all'||r.matches.some(m=>f==='parameter'?m.shared_attributes.length>0:m.relation===f)});$('rows').replaceChildren();
for(const c of values.slice(offset,offset+20)){let r=observations.get(c.id),tr=document.createElement('tr'),a=document.createElement('td'),b=document.createElement('td');a.textContent=c.source_occurrences?.[0]?.display_text||JSON.stringify(c.atom);b.textContent=r.matches.length?r.matches.map(m=>m.target_knowledge_id+' · '+m.relation+(m.shared_attributes.length?' · parameter':'')).join('; '):text('Не подтверждено целью','Not confirmed by target');tr.append(a,b);tr.onclick=()=>{$('details').textContent=JSON.stringify({candidate:c,evaluation:r},null,2);$('rows').querySelectorAll('tr').forEach(t=>t.classList.toggle('selected',t===tr))};$('rows').append(tr)}
if(!values.length){let tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=2;td.textContent=text('Кандидатов нет при заданных ограничениях.','No candidates under the configured constraints.');tr.append(td);$('rows').append(tr)}
$('prev').disabled=offset===0;$('next').disabled=offset+20>=values.length;$('page').textContent=(values.length?offset+1:0)+'–'+Math.min(offset+20,values.length)+' / '+values.length;$('versions').textContent=JSON.stringify({source_binding:D.sealed.binding,seal_sha256:D.evaluation.binding.prediction_sha256,evaluation_binding:D.evaluation.binding,diagnostics:D.sealed.diagnostics},null,2)}
for(const id of ['mode','filter','language'])$(id).onchange=()=>{offset=0;$('details').textContent='';render()};$('prev').onclick=()=>{offset=Math.max(0,offset-20);render()};$('next').onclick=()=>{offset+=20;render()};render();
</script></html>'''
